export enum PlotStatus {
  AVAILABLE = 'Available',
  BOOKED = 'Booked',
  SOLD = 'Sold'
}

// Represents a geometric plot detected by AI or defined manually
export interface PlotGeometry {
  id: string; // The detected text label (e.g., "101")
  box_2d: [number, number, number, number]; // [ymin, xmin, ymax, xmax] normalized 0-1000
}

// Represents the business data from CSV/Excel
export interface InventoryItem {
  plotId: string;
  status: PlotStatus;
  price?: number;
  sqFt?: number;
  customerName?: string;
  [key: string]: any;
}

// Merged data for the dashboard
export interface EnrichedPlot extends PlotGeometry {
  inventory?: InventoryItem;
}

export interface DashboardData {
  id: string;
  name: string;
  createdAt: number;
  layoutImage: string; // Base64 data URI
  plots: EnrichedPlot[];
}

export type ViewState = 'DIRECTORY' | 'WIZARD' | 'DASHBOARD';

export interface FileUploadState {
  imageFile: File | null;
  inventoryFile: File | null;
}

import { InventoryItem, PlotStatus } from '../types';

export const parseCSV = async (file: File): Promise<InventoryItem[]> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      const text = event.target?.result as string;
      if (!text) {
        resolve([]);
        return;
      }

      const lines = text.split('\n');
      if (lines.length < 2) {
        resolve([]);
        return;
      }

      const headers = lines[0].split(',').map(h => h.trim().toLowerCase());
      const data: InventoryItem[] = [];

      // Helper to find column index loosely
      const findCol = (terms: string[]) => headers.findIndex(h => terms.some(t => h.includes(t)));

      const idIdx = findCol(['plot', 'id', 'number', 'no']);
      const statusIdx = findCol(['status', 'state']);
      const priceIdx = findCol(['price', 'cost', 'amount']);
      const sqFtIdx = findCol(['sqft', 'area', 'size']);
      const nameIdx = findCol(['customer', 'buyer', 'name']);

      for (let i = 1; i < lines.length; i++) {
        const line = lines[i].trim();
        if (!line) continue;

        const values = line.split(',').map(v => v.trim());

        if (values[idIdx]) {
          let status = PlotStatus.AVAILABLE;
          const rawStatus = values[statusIdx]?.toLowerCase() || '';

          if (rawStatus.includes('sold')) status = PlotStatus.SOLD;
          else if (rawStatus.includes('book')) status = PlotStatus.BOOKED;

          data.push({
            plotId: values[idIdx],
            status,
            price: priceIdx > -1 ? parseFloat(values[priceIdx]) : undefined,
            sqFt: sqFtIdx > -1 ? parseFloat(values[sqFtIdx]) : undefined,
            customerName: nameIdx > -1 ? values[nameIdx] : undefined,
          });
        }
      }
      resolve(data);
    };
    reader.onerror = (e) => reject(e);
    reader.readAsText(file);
  });
};

export const fileToBase64 = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

import { GoogleGenAI, Type } from "@google/genai";
import { PlotGeometry } from '../types';

// Initialize Gemini Client
// In a real app, strict error handling for missing API key would be here.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeLayoutImage = async (base64Image: string): Promise<PlotGeometry[]> => {
  if (!process.env.API_KEY) {
    console.warn("No API Key found. Returning mock data for demonstration.");
    return getMockPlots(); 
  }

  // Remove data URL header if present for the API call
  const base64Data = base64Image.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, '');
  const mimeType = base64Image.match(/data:([^;]*);/)?.[1] || 'image/png';

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image', // Using Flash for speed/cost on image tasks
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Data
            }
          },
          {
            text: `Analyze this real estate layout plan. 
            Identify all individual plots or lots. 
            For each plot, extract its Label (number or ID) and its bounding box.
            The bounding box should be normalized coordinates [ymin, xmin, ymax, xmax] on a scale of 0 to 1000.

            Return the result in JSON format.`
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            plots: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING, description: "The plot number or label visible on the image" },
                  box_2d: { 
                    type: Type.ARRAY, 
                    items: { type: Type.NUMBER }, 
                    description: "ymin, xmin, ymax, xmax (0-1000 scale)" 
                  }
                },
                required: ["id", "box_2d"]
              }
            }
          }
        }
      }
    });

    const jsonText = response.text || "{}";
    const result = JSON.parse(jsonText);

    if (result.plots && Array.isArray(result.plots)) {
      return result.plots;
    }
    return [];

  } catch (error) {
    console.error("Gemini Analysis Failed:", error);
    // Fallback for demo purposes if API fails or key is invalid
    return getMockPlots();
  }
};

const getMockPlots = (): PlotGeometry[] => {
  // Mock data representing a simple grid for demo resilience
  const plots: PlotGeometry[] = [];
  let id = 1;
  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 5; col++) {
      plots.push({
        id: `P-${id++}`,
        box_2d: [
          100 + row * 200, // ymin
          50 + col * 180,  // xmin
          250 + row * 200, // ymax
          200 + col * 180  // xmax
        ]
      });
    }
  }
  return plots;
}

import React, { useState, useMemo } from 'react';
import { DashboardData, PlotStatus, EnrichedPlot } from '../types';
import { User, DollarSign, maximize, Maximize2, Grid, Tag } from 'lucide-react';

interface DashboardProps {
  data: DashboardData;
}

export const Dashboard: React.FC<DashboardProps> = ({ data }) => {
  const [hoveredPlot, setHoveredPlot] = useState<EnrichedPlot | null>(null);
  const [filterStatus, setFilterStatus] = useState<PlotStatus | 'All'>('All');

  // SVG Coordinate system is 0-1000 based on the AI prompt request
  const SVG_SIZE = 1000;

  const getStatusColor = (status: PlotStatus) => {
    switch (status) {
      case PlotStatus.AVAILABLE: return 'fill-green-500/40 stroke-green-600';
      case PlotStatus.BOOKED: return 'fill-orange-500/40 stroke-orange-600';
      case PlotStatus.SOLD: return 'fill-red-500/40 stroke-red-600';
      default: return 'fill-gray-500/40 stroke-gray-600';
    }
  };

  const getStatusBadgeColor = (status: PlotStatus) => {
    switch (status) {
      case PlotStatus.AVAILABLE: return 'bg-green-100 text-green-800 border-green-200';
      case PlotStatus.BOOKED: return 'bg-orange-100 text-orange-800 border-orange-200';
      case PlotStatus.SOLD: return 'bg-red-100 text-red-800 border-red-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  const filteredPlots = useMemo(() => {
    if (filterStatus === 'All') return data.plots;
    return data.plots.filter(p => p.inventory?.status === filterStatus);
  }, [data.plots, filterStatus]);

  // Statistics
  const stats = useMemo(() => {
    const total = data.plots.length;
    const available = data.plots.filter(p => p.inventory?.status === PlotStatus.AVAILABLE).length;
    const booked = data.plots.filter(p => p.inventory?.status === PlotStatus.BOOKED).length;
    const sold = data.plots.filter(p => p.inventory?.status === PlotStatus.SOLD).length;
    return { total, available, booked, sold };
  }, [data.plots]);

  return (
    <div className="flex flex-col lg:flex-row h-full gap-6 p-6">

      {/* Left Panel: Map */}
      <div className="flex-1 flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden relative">
        <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
          <h2 className="font-semibold text-slate-700 flex items-center gap-2">
            <Grid size={18} /> Plot Layout Map
          </h2>
          <div className="flex gap-2 text-xs">
            {Object.values(PlotStatus).map(status => (
              <div key={status} className="flex items-center gap-1 px-2 py-1 bg-white rounded border border-slate-200 shadow-sm">
                <div className={`w-3 h-3 rounded-full ${getStatusColor(status).replace('/40', '')} border-none`}></div>
                <span>{status}</span>
              </div>
            ))}
          </div>
        </div>

        <div className="relative w-full h-full bg-slate-100 overflow-auto flex items-center justify-center p-4">
          <div className="relative shadow-xl max-w-full max-h-[80vh]" style={{ aspectRatio: 'auto' }}>
            <img 
              src={data.layoutImage} 
              alt="Layout" 
              className="block w-full h-auto max-w-4xl rounded"
            />

            {/* SVG Overlay */}
            <svg 
              viewBox={`0 0 ${SVG_SIZE} ${SVG_SIZE}`} 
              preserveAspectRatio="none"
              className="absolute top-0 left-0 w-full h-full"
            >
              {filteredPlots.map((plot) => {
                const [ymin, xmin, ymax, xmax] = plot.box_2d;
                const width = xmax - xmin;
                const height = ymax - ymin;
                const status = plot.inventory?.status || PlotStatus.AVAILABLE;

                return (
                  <g key={plot.id} 
                     className="cursor-pointer group transition-all duration-200"
                     onMouseEnter={() => setHoveredPlot(plot)}
                     onMouseLeave={() => setHoveredPlot(null)}
                  >
                    <rect
                      x={xmin}
                      y={ymin}
                      width={width}
                      height={height}
                      className={`${getStatusColor(status)} hover:fill-opacity-60 stroke-2`}
                    />
                    {/* Label inside plot if big enough */}
                    {width > 30 && height > 30 && (
                      <text 
                        x={xmin + width / 2} 
                        y={ymin + height / 2} 
                        textAnchor="middle" 
                        dominantBaseline="middle"
                        className="fill-slate-800 text-[20px] font-bold opacity-0 group-hover:opacity-100 pointer-events-none"
                      >
                        {plot.id}
                      </text>
                    )}
                  </g>
                );
              })}
            </svg>
          </div>
        </div>
      </div>

      {/* Right Panel: Info & Stats */}
      <div className="w-full lg:w-96 flex flex-col gap-6">

        {/* Stats Card */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
          <h3 className="text-sm font-semibold text-slate-500 uppercase tracking-wider mb-4">Inventory Summary</h3>
          <div className="grid grid-cols-2 gap-4">
             <div className="p-3 bg-blue-50 rounded-lg">
                <div className="text-2xl font-bold text-blue-600">{stats.total}</div>
                <div className="text-xs text-blue-400 font-medium">Total Plots</div>
             </div>
             <div className="p-3 bg-green-50 rounded-lg">
                <div className="text-2xl font-bold text-green-600">{stats.available}</div>
                <div className="text-xs text-green-400 font-medium">Available</div>
             </div>
             <div className="p-3 bg-orange-50 rounded-lg">
                <div className="text-2xl font-bold text-orange-600">{stats.booked}</div>
                <div className="text-xs text-orange-400 font-medium">Booked</div>
             </div>
             <div className="p-3 bg-red-50 rounded-lg">
                <div className="text-2xl font-bold text-red-600">{stats.sold}</div>
                <div className="text-xs text-red-400 font-medium">Sold</div>
             </div>
          </div>

          <div className="mt-6">
            <label className="text-xs font-semibold text-slate-500 mb-2 block">Filter View</label>
            <select 
              className="w-full p-2 border border-slate-200 rounded-md text-sm bg-slate-50 focus:ring-2 focus:ring-blue-500 outline-none"
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value as any)}
            >
              <option value="All">Show All</option>
              <option value={PlotStatus.AVAILABLE}>Available Only</option>
              <option value={PlotStatus.BOOKED}>Booked Only</option>
              <option value={PlotStatus.SOLD}>Sold Only</option>
            </select>
          </div>
        </div>

        {/* Detail Card - Sticky if needed, or static */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 flex-1 flex flex-col overflow-hidden">
          <div className="p-4 border-b border-slate-100 bg-slate-50">
            <h3 className="font-semibold text-slate-700">Plot Details</h3>
          </div>
          <div className="p-6 flex-1 flex flex-col justify-center">
            {hoveredPlot ? (
              <div className="space-y-6 animate-in fade-in slide-in-from-bottom-2 duration-200">
                <div className="flex justify-between items-start">
                  <div>
                    <span className="text-slate-400 text-xs font-bold uppercase">Plot Number</span>
                    <h1 className="text-4xl font-bold text-slate-800">{hoveredPlot.id}</h1>
                  </div>
                  <span className={`px-3 py-1 rounded-full text-xs font-semibold border ${getStatusBadgeColor(hoveredPlot.inventory?.status || PlotStatus.AVAILABLE)}`}>
                    {hoveredPlot.inventory?.status || 'Unknown'}
                  </span>
                </div>

                <div className="space-y-4">
                  <div className="flex items-center gap-3 p-3 bg-slate-50 rounded-lg border border-slate-100">
                    <Maximize2 className="text-slate-400" size={20} />
                    <div>
                      <p className="text-xs text-slate-500">Area Size</p>
                      <p className="font-medium text-slate-700">{hoveredPlot.inventory?.sqFt ? `${hoveredPlot.inventory.sqFt} sq.ft` : 'N/A'}</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-3 p-3 bg-slate-50 rounded-lg border border-slate-100">
                    <DollarSign className="text-slate-400" size={20} />
                    <div>
                      <p className="text-xs text-slate-500">Price</p>
                      <p className="font-medium text-slate-700">
                        {hoveredPlot.inventory?.price 
                          ? new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(hoveredPlot.inventory.price) 
                          : 'Contact for Price'}
                      </p>
                    </div>
                  </div>

                  {(hoveredPlot.inventory?.status === PlotStatus.SOLD || hoveredPlot.inventory?.status === PlotStatus.BOOKED) && (
                    <div className="flex items-center gap-3 p-3 bg-slate-50 rounded-lg border border-slate-100">
                      <User className="text-slate-400" size={20} />
                      <div>
                        <p className="text-xs text-slate-500">Customer</p>
                        <p className="font-medium text-slate-700">{hoveredPlot.inventory?.customerName || 'Private'}</p>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            ) : (
              <div className="text-center text-slate-400">
                <Tag size={48} className="mx-auto mb-3 opacity-20" />
                <p>Hover over a plot on the map to view detailed inventory information.</p>
              </div>
            )}
          </div>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useRef } from 'react';
import { UploadCloud, FileSpreadsheet, Image as ImageIcon, Loader2 } from 'lucide-react';
import { FileUploadState } from '../types';

interface UploadWizardProps {
  onProcess: (files: FileUploadState) => void;
  isProcessing: boolean;
}

export const UploadWizard: React.FC<UploadWizardProps> = ({ onProcess, isProcessing }) => {
  const [files, setFiles] = useState<FileUploadState>({ imageFile: null, inventoryFile: null });
  const [dragActive, setDragActive] = useState(false);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const csvInputRef = useRef<HTMLInputElement>(null);

  const handleDrag = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      // Simple heuristic: if it's an image, set image; if csv/xlsx, set inventory
      const file = e.dataTransfer.files[0];
      if (file.type.startsWith('image/')) {
        setFiles(prev => ({ ...prev, imageFile: file }));
      } else if (file.name.endsWith('.csv') || file.name.endsWith('.xlsx')) {
        setFiles(prev => ({ ...prev, inventoryFile: file }));
      }
    }
  };

  const isReady = files.imageFile && files.inventoryFile;

  return (
    <div className="max-w-3xl mx-auto py-12 px-6">
      <div className="text-center mb-10">
        <h1 className="text-3xl font-bold text-slate-800 mb-2">Create New Inventory Dashboard</h1>
        <p className="text-slate-500">Upload your plot layout image and inventory data to generate an interactive map.</p>
      </div>

      <div className="grid md:grid-cols-2 gap-6">

        {/* Image Upload */}
        <div 
          className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center text-center transition-colors cursor-pointer
            ${files.imageFile ? 'border-blue-500 bg-blue-50' : 'border-slate-300 hover:border-slate-400 hover:bg-slate-50'}`}
          onClick={() => imageInputRef.current?.click()}
        >
          <input 
            type="file" 
            ref={imageInputRef} 
            className="hidden" 
            accept="image/*"
            onChange={(e) => e.target.files && setFiles(prev => ({ ...prev, imageFile: e.target.files![0] }))}
          />
          {files.imageFile ? (
            <>
              <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mb-4">
                <ImageIcon size={32} />
              </div>
              <p className="font-semibold text-slate-700 break-all">{files.imageFile.name}</p>
              <p className="text-xs text-blue-600 mt-2">Click to replace</p>
            </>
          ) : (
            <>
              <div className="w-16 h-16 bg-slate-100 text-slate-400 rounded-full flex items-center justify-center mb-4">
                <ImageIcon size={32} />
              </div>
              <p className="font-semibold text-slate-700">Upload Layout</p>
              <p className="text-xs text-slate-500 mt-1">PNG, JPG, SVG</p>
            </>
          )}
        </div>

        {/* CSV Upload */}
        <div 
          className={`border-2 border-dashed rounded-xl p-8 flex flex-col items-center justify-center text-center transition-colors cursor-pointer
            ${files.inventoryFile ? 'border-green-500 bg-green-50' : 'border-slate-300 hover:border-slate-400 hover:bg-slate-50'}`}
          onClick={() => csvInputRef.current?.click()}
        >
          <input 
            type="file" 
            ref={csvInputRef} 
            className="hidden" 
            accept=".csv"
            onChange={(e) => e.target.files && setFiles(prev => ({ ...prev, inventoryFile: e.target.files![0] }))}
          />
           {files.inventoryFile ? (
            <>
              <div className="w-16 h-16 bg-green-100 text-green-600 rounded-full flex items-center justify-center mb-4">
                <FileSpreadsheet size={32} />
              </div>
              <p className="font-semibold text-slate-700 break-all">{files.inventoryFile.name}</p>
              <p className="text-xs text-green-600 mt-2">Click to replace</p>
            </>
          ) : (
            <>
              <div className="w-16 h-16 bg-slate-100 text-slate-400 rounded-full flex items-center justify-center mb-4">
                <FileSpreadsheet size={32} />
              </div>
              <p className="font-semibold text-slate-700">Upload Inventory</p>
              <p className="text-xs text-slate-500 mt-1">CSV Format</p>
            </>
          )}
        </div>
      </div>

      {/* Action Area */}
      <div className="mt-10 flex flex-col items-center">
        <button 
          onClick={() => isReady && onProcess(files)}
          disabled={!isReady || isProcessing}
          className={`
            flex items-center gap-3 px-8 py-4 rounded-lg font-bold text-lg shadow-lg transition-all
            ${isReady && !isProcessing
              ? 'bg-blue-600 text-white hover:bg-blue-700 hover:scale-105' 
              : 'bg-slate-200 text-slate-400 cursor-not-allowed'}
          `}
        >
          {isProcessing ? (
            <>
              <Loader2 className="animate-spin" /> Processing AI Analysis...
            </>
          ) : (
            <>
              <UploadCloud /> Generate Dashboard
            </>
          )}
        </button>
        <p className="text-xs text-slate-400 mt-4 text-center max-w-md">
          The system will analyze the image using Gemini AI to detect plot boundaries and map them to your inventory file automatically.
        </p>
      </div>
    </div>
  );
};

