import React, { useState, useEffect } from 'react';
import { DashboardData, FileUploadState, ViewState, EnrichedPlot } from './types';
import { analyzeLayoutImage } from './services/geminiService';
import { parseCSV, fileToBase64 } from './utils/csvParser';
import { UploadWizard } from './components/UploadWizard';
import { Dashboard } from './components/Dashboard';
import { Directory } from './components/Directory';
import { FolderOpen, Save, RotateCcw, Layout, ArrowLeft } from 'lucide-react';

const STORAGE_KEY = 'estatevision_dashboards';

export default function App() {
  const [view, setView] = useState<ViewState>('DIRECTORY');
  const [dashboards, setDashboards] = useState<DashboardData[]>([]);
  const [currentDashboard, setCurrentDashboard] = useState<DashboardData | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // Load from local storage on mount
  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        setDashboards(JSON.parse(saved));
      } catch (e) {
        console.error("Failed to load dashboards", e);
      }
    }
  }, []);

  const handleProcessFiles = async (files: FileUploadState) => {
    if (!files.imageFile || !files.inventoryFile) return;

    setIsProcessing(true);
    try {
      // 1. Convert Image to Base64
      const base64Img = await fileToBase64(files.imageFile);

      // 2. Parse CSV
      const inventoryData = await parseCSV(files.inventoryFile);

      // 3. AI Analysis of Image
      const plotsGeometry = await analyzeLayoutImage(base64Img);

      // 4. Merge Data
      const enrichedPlots: EnrichedPlot[] = plotsGeometry.map(geom => {
        // Simple matching logic: Clean IDs and find exact match
        const matchingInventory = inventoryData.find(inv => 
          inv.plotId.toString().toLowerCase() === geom.id.toString().toLowerCase()
        );
        return {
          ...geom,
          inventory: matchingInventory
        };
      });

      // 5. Create Dashboard Object
      const newDashboard: DashboardData = {
        id: crypto.randomUUID(),
        name: files.imageFile.name.split('.')[0] + ' Dashboard',
        createdAt: Date.now(),
        layoutImage: base64Img,
        plots: enrichedPlots
      };

      setCurrentDashboard(newDashboard);
      setView('DASHBOARD');

    } catch (error) {
      console.error("Processing error:", error);
      alert("An error occurred while processing the files. Please try again.");
    } finally {
      setIsProcessing(false);
    }
  };

  const handleSave = () => {
    if (!currentDashboard) return;

    // Check if updating existing or saving new (for this logic, we always append new if ID doesn't exist)
    const existingIdx = dashboards.findIndex(d => d.id === currentDashboard.id);
    let updatedDashboards;

    if (existingIdx >= 0) {
      updatedDashboards = [...dashboards];
      updatedDashboards[existingIdx] = currentDashboard;
    } else {
      updatedDashboards = [...dashboards, currentDashboard];
    }

    setDashboards(updatedDashboards);
    localStorage.setItem(STORAGE_KEY, JSON.stringify(updatedDashboards));
    alert("Dashboard saved successfully!");
  };

  const handleReset = () => {
    if (window.confirm("Are you sure you want to reset? Unsaved changes will be lost.")) {
      setCurrentDashboard(null);
      setView('WIZARD');
    }
  };

  const handleDelete = (id: string) => {
    if (window.confirm("Delete this dashboard?")) {
      const updated = dashboards.filter(d => d.id !== id);
      setDashboards(updated);
      localStorage.setItem(STORAGE_KEY, JSON.stringify(updated));
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-slate-50 text-slate-800 font-sans">

      {/* App Header */}
      <header className="bg-white border-b border-slate-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-4 h-16 flex items-center justify-between">

          <div className="flex items-center gap-2 cursor-pointer" onClick={() => setView('DIRECTORY')}>
            <div className="bg-blue-600 text-white p-1.5 rounded-lg">
               <Layout size={20} />
            </div>
            <span className="font-bold text-lg tracking-tight">EstateVision AI</span>
          </div>

          <div className="flex items-center gap-3">
            {view === 'DASHBOARD' && (
              <>
                 <button 
                  onClick={() => setView('DIRECTORY')}
                  className="flex items-center gap-2 px-3 py-1.5 text-slate-600 hover:bg-slate-100 rounded-md text-sm font-medium transition-colors"
                >
                  <FolderOpen size={16} /> Directory
                </button>
                <div className="h-6 w-px bg-slate-200 mx-1"></div>
                <button 
                  onClick={handleReset}
                  className="flex items-center gap-2 px-3 py-1.5 text-slate-600 hover:bg-slate-100 rounded-md text-sm font-medium transition-colors"
                >
                  <RotateCcw size={16} /> Reset
                </button>
                <button 
                  onClick={handleSave}
                  className="flex items-center gap-2 px-4 py-1.5 bg-blue-600 text-white rounded-md text-sm font-medium hover:bg-blue-700 transition-colors shadow-sm"
                >
                  <Save size={16} /> Save
                </button>
              </>
            )}

            {view === 'WIZARD' && (
               <button 
                onClick={() => setView('DIRECTORY')}
                className="flex items-center gap-2 px-3 py-1.5 text-slate-500 hover:text-slate-800 text-sm font-medium transition-colors"
              >
                <ArrowLeft size={16} /> Back to Directory
              </button>
            )}
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 overflow-hidden">
        {view === 'DIRECTORY' && (
          <Directory 
            dashboards={dashboards} 
            onSelect={(id) => {
              const dash = dashboards.find(d => d.id === id);
              if (dash) {
                setCurrentDashboard(dash);
                setView('DASHBOARD');
              }
            }}
            onDelete={handleDelete}
            onCreateNew={() => setView('WIZARD')}
          />
        )}

        {view === 'WIZARD' && (
          <UploadWizard onProcess={handleProcessFiles} isProcessing={isProcessing} />
        )}

        {view === 'DASHBOARD' && currentDashboard && (
          <Dashboard data={currentDashboard} />
        )}
      </main>

    </div>
  );
}

import { GoogleGenAI, Type } from "@google/genai";
import { PlotGeometry } from '../types';

// Initialize Gemini Client
// In a real app, strict error handling for missing API key would be here.
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const analyzeLayoutImage = async (base64Image: string): Promise<PlotGeometry[]> => {
  if (!process.env.API_KEY) {
    console.warn("No API Key found. Returning mock data for demonstration.");
    return getMockPlots(); 
  }

  // Remove data URL header if present for the API call
  const base64Data = base64Image.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, '');
  const mimeType = base64Image.match(/data:([^;]*);/)?.[1] || 'image/png';

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: mimeType,
              data: base64Data
            }
          },
          {
            text: `You are an expert real estate layout analyzer.

            Task: detailed extraction of all plots from the provided real estate layout image.

            Instructions:
            1. Identify every single plot, lot, or unit that has a number or label (e.g., "1", "101", "A-5", "Plot 4").
            2. For each plot, determine its PRECISE bounding box. The box should encompass the entire boundary of the plot, not just the text label.
            3. Return the coordinates normalized to a 0-1000 scale [ymin, xmin, ymax, xmax].
            4. Be extremely thorough. If there are 50 plots, return 50 entries.

            Output strictly valid JSON matching the schema.`
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            plots: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  id: { type: Type.STRING, description: "The distinct plot number or label visible on the image" },
                  box_2d: { 
                    type: Type.ARRAY, 
                    items: { type: Type.NUMBER }, 
                    description: "ymin, xmin, ymax, xmax (0-1000 scale)" 
                  }
                },
                required: ["id", "box_2d"]
              }
            }
          }
        }
      }
    });

    const jsonText = response.text || "{}";
    const result = JSON.parse(jsonText);

    if (result.plots && Array.isArray(result.plots)) {
      return result.plots;
    }
    return [];

  } catch (error) {
    console.error("Gemini Analysis Failed:", error);
    // Fallback for demo purposes if API fails or key is invalid
    return getMockPlots();
  }
};

const getMockPlots = (): PlotGeometry[] => {
  // Mock data representing a simple grid for demo resilience
  const plots: PlotGeometry[] = [];
  let id = 1;
  for (let row = 0; row < 4; row++) {
    for (let col = 0; col < 5; col++) {
      plots.push({
        id: `P-${id++}`,
        box_2d: [
          100 + row * 200, // ymin
          50 + col * 180,  // xmin
          250 + row * 200, // ymax
          200 + col * 180  // xmax
        ]
      });
    }
  }
  return plots;
}

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { DashboardData, PlotStatus, EnrichedPlot } from '../types';
import { User, DollarSign, Maximize2, Grid, Tag, ZoomIn, ZoomOut, RotateCcw, Move } from 'lucide-react';

interface DashboardProps {
  data: DashboardData;
}

export const Dashboard: React.FC<DashboardProps> = ({ data }) => {
  const [hoveredPlot, setHoveredPlot] = useState<EnrichedPlot | null>(null);
  const [filterStatus, setFilterStatus] = useState<PlotStatus | 'All'>('All');

  // Transform State for Zoom/Pan
  const [transform, setTransform] = useState({ scale: 1, x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });
  const containerRef = useRef<HTMLDivElement>(null);

  // Tooltip State
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  // SVG Coordinate system is 0-1000 based on the AI prompt request
  const SVG_SIZE = 1000;

  const getStatusColor = (status: PlotStatus) => {
    switch (status) {
      case PlotStatus.AVAILABLE: return 'fill-green-500/30 stroke-green-600';
      case PlotStatus.BOOKED: return 'fill-orange-500/30 stroke-orange-600';
      case PlotStatus.SOLD: return 'fill-red-500/30 stroke-red-600';
      default: return 'fill-gray-500/30 stroke-gray-600';
    }
  };

  const getStatusBadgeColor = (status: PlotStatus) => {
    switch (status) {
      case PlotStatus.AVAILABLE: return 'bg-green-100 text-green-800 border-green-200';
      case PlotStatus.BOOKED: return 'bg-orange-100 text-orange-800 border-orange-200';
      case PlotStatus.SOLD: return 'bg-red-100 text-red-800 border-red-200';
      default: return 'bg-gray-100 text-gray-800 border-gray-200';
    }
  };

  const filteredPlots = useMemo(() => {
    if (filterStatus === 'All') return data.plots;
    return data.plots.filter(p => p.inventory?.status === filterStatus);
  }, [data.plots, filterStatus]);

  // Statistics
  const stats = useMemo(() => {
    const total = data.plots.length;
    const available = data.plots.filter(p => p.inventory?.status === PlotStatus.AVAILABLE).length;
    const booked = data.plots.filter(p => p.inventory?.status === PlotStatus.BOOKED).length;
    const sold = data.plots.filter(p => p.inventory?.status === PlotStatus.SOLD).length;
    return { total, available, booked, sold };
  }, [data.plots]);

  // --- Zoom & Pan Handlers ---

  const handleWheel = (e: React.WheelEvent) => {
    // Zoom centered on pointer
    if (!containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    // Calculate mouse position in "content" coordinates before zoom
    const contentX = (mouseX - transform.x) / transform.scale;
    const contentY = (mouseY - transform.y) / transform.scale;

    const scaleSensitivity = 0.001;
    const delta = -e.deltaY * scaleSensitivity;
    const newScale = Math.min(Math.max(0.5, transform.scale + delta), 8);

    // Calculate new translation to keep content point at mouse position
    const newX = mouseX - (contentX * newScale);
    const newY = mouseY - (contentY * newScale);

    setTransform({ scale: newScale, x: newX, y: newY });
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (e.button !== 0) return; // Only left click
    setIsDragging(true);
    setDragStart({ x: e.clientX - transform.x, y: e.clientY - transform.y });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    // Update tooltip position regardless of dragging
    if (containerRef.current) {
        const rect = containerRef.current.getBoundingClientRect();
        setMousePos({ x: e.clientX - rect.left, y: e.clientY - rect.top });
    }

    if (isDragging) {
      setTransform(prev => ({
        ...prev,
        x: e.clientX - dragStart.x,
        y: e.clientY - dragStart.y
      }));
    }
  };

  const handleMouseUp = () => {
    setIsDragging(false);
  };

  const resetZoom = () => {
    setTransform({ scale: 1, x: 0, y: 0 });
  };

  const zoomIn = () => {
     setTransform(prev => ({ ...prev, scale: Math.min(prev.scale * 1.2, 8) }));
  };

  const zoomOut = () => {
     setTransform(prev => ({ ...prev, scale: Math.max(prev.scale / 1.2, 0.5) }));
  };

  return (
    <div className="flex flex-col lg:flex-row h-full gap-6 p-6">

      {/* Left Panel: Map */}
      <div className="flex-1 flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden relative group">

        {/* Map Header / Toolbar */}
        <div className="p-3 border-b border-slate-100 flex justify-between items-center bg-slate-50 z-10 relative shadow-sm">
          <div className="flex items-center gap-2">
            <h2 className="font-semibold text-slate-700 flex items-center gap-2 text-sm">
              <Grid size={16} /> Layout Map
            </h2>
            <div className="h-4 w-px bg-slate-300 mx-2"></div>
            <div className="flex gap-2">
               <button onClick={zoomIn} className="p-1 hover:bg-white rounded border border-transparent hover:border-slate-200 text-slate-600" title="Zoom In">
                  <ZoomIn size={16} />
               </button>
               <button onClick={zoomOut} className="p-1 hover:bg-white rounded border border-transparent hover:border-slate-200 text-slate-600" title="Zoom Out">
                  <ZoomOut size={16} />
               </button>
               <button onClick={resetZoom} className="p-1 hover:bg-white rounded border border-transparent hover:border-slate-200 text-slate-600" title="Reset View">
                  <RotateCcw size={16} />
               </button>
            </div>
          </div>

          <div className="flex gap-2 text-xs">
            {Object.values(PlotStatus).map(status => (
              <div key={status} className="flex items-center gap-1 px-2 py-1 bg-white rounded border border-slate-200 shadow-sm">
                <div className={`w-2.5 h-2.5 rounded-full ${getStatusColor(status).replace('/30', '')} border-none`}></div>
                <span>{status}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Map Container - Handles Zoom/Pan */}
        <div 
          ref={containerRef}
          className={`relative w-full h-full bg-slate-100 overflow-hidden ${isDragging ? 'cursor-grabbing' : 'cursor-grab'}`}
          onWheel={handleWheel}
          onMouseDown={handleMouseDown}
          onMouseMove={handleMouseMove}
          onMouseUp={handleMouseUp}
          onMouseLeave={handleMouseUp}
        >
          <div 
            className="origin-top-left transition-transform duration-75 ease-out"
            style={{ transform: `translate(${transform.x}px, ${transform.y}px) scale(${transform.scale})` }}
          >
            <div className="relative inline-block shadow-xl">
              <img 
                src={data.layoutImage} 
                alt="Layout" 
                className="block max-w-none rounded select-none pointer-events-none"
                style={{ width: '1000px' }} // Normalize render width to match SVG ViewBox ratio concept essentially
                draggable={false}
              />

              {/* SVG Overlay */}
              <svg 
                viewBox={`0 0 ${SVG_SIZE} ${SVG_SIZE}`} 
                preserveAspectRatio="none"
                className="absolute top-0 left-0 w-full h-full"
              >
                {filteredPlots.map((plot) => {
                  const [ymin, xmin, ymax, xmax] = plot.box_2d;
                  const width = xmax - xmin;
                  const height = ymax - ymin;
                  const status = plot.inventory?.status || PlotStatus.AVAILABLE;

                  return (
                    <g key={plot.id} 
                       className="cursor-pointer transition-all duration-200"
                       onMouseEnter={() => setHoveredPlot(plot)}
                       onMouseLeave={() => setHoveredPlot(null)}
                    >
                      <rect
                        x={xmin}
                        y={ymin}
                        width={width}
                        height={height}
                        className={`${getStatusColor(status)} hover:fill-opacity-60 stroke-[3px] vector-effect-non-scaling-stroke`}
                      />
                      {/* Label inside plot - scales with zoom but text size stays relatively readable via minimal scale logic? No, let's keep it simple. */}
                      {width > 20 && height > 20 && (
                        <text 
                          x={xmin + width / 2} 
                          y={ymin + height / 2} 
                          textAnchor="middle" 
                          dominantBaseline="middle"
                          className="fill-slate-900 text-[24px] font-extrabold opacity-60 pointer-events-none drop-shadow-sm"
                          style={{ textShadow: '0px 0px 2px rgba(255,255,255,0.8)' }}
                        >
                          {plot.id}
                        </text>
                      )}
                    </g>
                  );
                })}
              </svg>
            </div>
          </div>

          {/* Floating Tooltip */}
          {hoveredPlot && (
            <div 
              className="absolute pointer-events-none z-50 bg-white/95 backdrop-blur-sm p-3 rounded-lg shadow-xl border border-slate-200 w-56 animate-in fade-in zoom-in-95 duration-150"
              style={{ 
                left: mousePos.x + 15, 
                top: mousePos.y + 15 
              }}
            >
              <div className="flex justify-between items-start mb-2 border-b border-slate-100 pb-2">
                <span className="font-bold text-lg text-slate-800">{hoveredPlot.id}</span>
                <span className={`text-[10px] uppercase font-bold px-2 py-0.5 rounded-full ${getStatusBadgeColor(hoveredPlot.inventory?.status || PlotStatus.AVAILABLE)}`}>
                  {hoveredPlot.inventory?.status || 'Unknown'}
                </span>
              </div>
              <div className="space-y-1 text-xs text-slate-600">
                <div className="flex justify-between">
                    <span>Size:</span>
                    <span className="font-medium">{hoveredPlot.inventory?.sqFt || '-'} sqft</span>
                </div>
                <div className="flex justify-between">
                    <span>Price:</span>
                    <span className="font-medium text-slate-900">
                      {hoveredPlot.inventory?.price ? `$${hoveredPlot.inventory.price.toLocaleString()}` : '-'}
                    </span>
                </div>
                {hoveredPlot.inventory?.customerName && (
                  <div className="flex justify-between text-blue-600">
                      <span>Owner:</span>
                      <span className="font-medium truncate max-w-[100px]">{hoveredPlot.inventory.customerName}</span>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Right Panel: Info & Stats */}
      <div className="w-full lg:w-96 flex flex-col gap-6">

        {/* Stats Card */}
        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
          <h3 className="text-sm font-semibold text-slate-500 uppercase tracking-wider mb-4">Inventory Summary</h3>
          <div className="grid grid-cols-2 gap-4">
             <div className="p-3 bg-blue-50 rounded-lg">
                <div className="text-2xl font-bold text-blue-600">{stats.total}</div>
                <div className="text-xs text-blue-400 font-medium">Total Plots</div>
             </div>
             <div className="p-3 bg-green-50 rounded-lg">
                <div className="text-2xl font-bold text-green-600">{stats.available}</div>
                <div className="text-xs text-green-400 font-medium">Available</div>
             </div>
             <div className="p-3 bg-orange-50 rounded-lg">
                <div className="text-2xl font-bold text-orange-600">{stats.booked}</div>
                <div className="text-xs text-orange-400 font-medium">Booked</div>
             </div>
             <div className="p-3 bg-red-50 rounded-lg">
                <div className="text-2xl font-bold text-red-600">{stats.sold}</div>
                <div className="text-xs text-red-400 font-medium">Sold</div>
             </div>
          </div>

          <div className="mt-6">
            <label className="text-xs font-semibold text-slate-500 mb-2 block">Filter View</label>
            <select 
              className="w-full p-2 border border-slate-200 rounded-md text-sm bg-slate-50 focus:ring-2 focus:ring-blue-500 outline-none"
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value as any)}
            >
              <option value="All">Show All</option>
              <option value={PlotStatus.AVAILABLE}>Available Only</option>
              <option value={PlotStatus.BOOKED}>Booked Only</option>
