                          y={ymin + height / 2} 
                          textAnchor="middle" 
                          dominantBaseline="middle"
                          className={`
                            font-extrabold pointer-events-none drop-shadow-sm
                            ${isSelected ? 'fill-blue-900 opacity-100' : 'fill-slate-900 opacity-70'}
